// ---------------------------------------------------------------------------
// 5. Helpers
// ---------------------------------------------------------------------------

const EMAIL_RE = /[a-z0-9._%+-]+@[a-z0-9.-]+\.[a-z]{2,}/i;
const PHONE_RE = /(\+?\d[\d\s()-]{7,}\d)/;

function normalise(s) {
  return String(s || '')
    .toLowerCase()
    .replace(/[‘’]/g, "'")
    .replace(/[“”]/g, '"')
    .replace(/\s+/g, ' ')
    .trim();
}

// Small, stable hash so a given session/turn always picks the same variant
// (repeatable in testing) while different visitors see different wording.
function seed(str) {
  let h = 2166136261;
  for (let i = 0; i < str.length; i++) {
    h ^= str.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  return Math.abs(h);
}

function pick(list, s) {
  if (!list || list.length === 0) return '';
  return list[s % list.length];
}

function matchFirst(patterns, text) {
  for (const [key, re] of patterns) {
    if (re.test(text)) return key;
  }
  return null;
}

function scoreIntents(text) {
  const scores = {};
  for (const [id, weight, re] of INTENT_RULES) {
    if (re.test(text)) scores[id] = (scores[id] || 0) + weight;
  }
  return scores;
}

function topIntent(scores) {
  let best = null;
  let bestScore = 0;
  for (const id of Object.keys(scores)) {
    if (scores[id] > bestScore) {
      best = id;
      bestScore = scores[id];
    }
  }
  return { intent: best, score: bestScore };
}

// ---------------------------------------------------------------------------
// 6. Main
// ---------------------------------------------------------------------------

const body = $input.first().json.body || {};
const rawMessage = String(body.message || '').trim().slice(0, 600);
const sessionId = String(body.sessionId || '');

const rawHistory = Array.isArray(body.history) ? body.history : [];
const history = rawHistory
  .filter((m) => m && typeof m.content === 'string' && (m.role === 'user' || m.role === 'assistant'))
  .slice(-6)
  .map((m) => ({ role: m.role, content: String(m.content).slice(0, 600) }));

const text = normalise(rawMessage);
const priorUser = history.filter((m) => m.role === 'user').map((m) => normalise(m.content));
const priorBot = history.filter((m) => m.role === 'assistant').map((m) => m.content);
const turn = priorUser.length;

// Topic carried from the last two visitor turns, so "how much?" after a job
// question stays a careers answer instead of becoming a quote pitch.
let topic = null;
for (const p of priorUser.slice(-2).reverse()) {
  const t = topIntent(scoreIntents(p));
  if (t.intent && t.score >= 3) {
    topic = t.intent;
    break;
  }
}

const scores = scoreIntents(text);

// A careers conversation reinterprets money and requirement questions.
if (topic && topic.startsWith('careers')) {
  if (scores.pricing || scores.quote) {
    scores.careers_pay = (scores.careers_pay || 0) + 5;
    delete scores.pricing;
    delete scores.quote;
  }
  if (scores.careers_apply) scores.careers_apply += 2;
}
// Likewise, an unhappy existing client asking "what now" is not a new lead.
if (topic === 'complaint' && scores.quote) delete scores.quote;

let { intent, score } = topIntent(scores);
let confidence = score >= 4 ? 'high' : score >= 2 ? 'medium' : 'low';

const job = matchFirst(JOB_PATTERNS, text);
const premises = matchFirst(PREMISES_PATTERNS, text);
const service = job || premises;
const hasEmail = EMAIL_RE.test(rawMessage);
const hasPhone = PHONE_RE.test(rawMessage);

// A bare "yes"/"how much?" resolves against the running topic.
if (!intent && FOLLOWUP_RE.test(text) && topic) {
  intent = topic;
  confidence = 'medium';
}

// Sticky topics: an unresolved message inside a live complaint or job
// conversation belongs to that conversation, not to a fresh quote pitch.
const STICKY = ['complaint', 'careers_apply', 'careers_pay', 'careers_requirements', 'existing_client', 'cancel', 'reschedule', 'subcontractor'];
let continuation = false;
if (!intent && topic && STICKY.indexOf(topic) !== -1) {
  intent = topic;
  confidence = 'medium';
  continuation = true;
}

// A named service with no other signal is a service question.
if (!intent && service) {
  intent = 'service_specific';
  confidence = 'medium';
}
if (intent === 'services_list' && service) intent = 'service_specific';

// Contact details handed over: the visitor wants a callback. Informational
// intents still get their answer, with the handover acknowledged after it.
const INFORMATIONAL = ['insurance', 'police_check', 'hours', 'coverage', 'services_list', 'service_specific', 'products', 'guarantee', 'staff', 'reviews', 'address', 'privacy', 'frequency', 'after_hours', 'contract', 'payment', 'insurance_docs', 'site_visit'];
let noteContact = false;
if (hasEmail || hasPhone) {
  // A message that is essentially just contact details carries no intent of
  // its own — answer the handover, in the language of the running topic.
  const bareContact = score < 2;
  if (bareContact || !intent || ['human', 'quote', 'pricing', 'urgent', 'greeting', 'thanks'].indexOf(intent) !== -1) {
    intent = topic && topic.startsWith('careers') ? 'contact_shared_careers' : 'contact_shared';
    confidence = 'high';
    continuation = false;
  } else if (INFORMATIONAL.indexOf(intent) !== -1 || STICKY.indexOf(intent) !== -1) {
    noteContact = true;
  }
}

// First message with nothing else in it is a greeting.
if (!intent && turn === 0 && text.length <= 25) {
  intent = 'greeting';
  confidence = 'medium';
}

const spec = intent ? BODIES[intent] : null;

// ---------------------------------------------------------------------------
// 7. Compose
// ---------------------------------------------------------------------------

const CONT_LEADS = ['Understood. ', 'Thanks for the extra detail. ', 'Noted. ', 'Right. '];

function fillSlots(s) {
  const svc = service ? SERVICES[service] : null;
  // "end-of-lease cleaning for a retail site" when both slots are filled.
  const forPremises = job && premises && premises !== job ? ` for ${SERVICES[premises].label.replace(/ cleaning.*$/, '')} sites` : '';
  return s
    .replace(/%svc%/g, svc ? svc.label : 'commercial cleaning')
    .replace(/%for%/g, forPremises)
    .replace(/%svcline%/g, svc ? svc.line : 'The schedule is built around your operating hours rather than ours.');
}

function compose() {
  const base = seed(sessionId + '|' + intent + '|' + turn);
  const ackPool = spec.ack === 'none' ? [''] : ACKS[spec.ack] || ACKS.neutral;
  let ack = turn === 0 && spec.ack === 'neutral' ? '' : pick(ackPool, base);

  // A continuation must not replay the answer the visitor just read.
  const bodyIdx = continuation ? (base >> 3) + 1 : base >> 3;
  if (continuation) ack = pick(CONT_LEADS, base);
  let bodyText = fillSlots(pick(spec.bodies, bodyIdx));
  if (continuation && priorBot.some((b) => b.indexOf(bodyText.slice(0, 40)) !== -1)) {
    bodyText = fillSlots(pick(spec.bodies, bodyIdx + 1));
  }

  const nextPool = NEXT[spec.next] || NEXT.none;
  let next = pick(nextPool, base >> 7);
  // Never ask the same closing question twice in a row.
  if (next && priorBot.some((b) => b.indexOf(next) !== -1)) {
    next = pick(nextPool, (base >> 7) + 1);
    if (priorBot.some((b) => b.indexOf(next) !== -1)) next = '';
  }

  const prefix = continuation ? '' : spec.prefix ? fillSlots(spec.prefix) : '';
  const sentence = prefix + bodyText;
  const lead = ack + sentence.charAt(0).toUpperCase() + sentence.slice(1);
  const noted = noteContact
    ? "I've also noted your contact details and passed them to the team so they can follow up."
    : '';

  return [lead, noted, next].filter(Boolean).join(' ').replace(/\s+/g, ' ').trim();
}

// Text used if the model branch times out — intent-aware, not generic.
function clarifyText() {
  if (intent && intent.startsWith('careers')) {
    return `For anything about roles at ${B.name}, email ${B.email} with your experience and availability, or call ${B.phone} during business hours.`;
  }
  if (intent === 'complaint' || intent === 'existing_client' || intent === 'reschedule' || intent === 'cancel') {
    return `Please call ${B.phone} so the team can sort this out against your account directly — that's faster and more reliable than this chat.`;
  }
  return `I want to get that right rather than guess. Could you tell me a bit more — or call ${B.phone} / email ${B.email} and the team will answer properly.`;
}

if (spec) {
  return [
    {
      json: {
        direct: true,
        reply: compose(),
        intent,
        confidence,
        service: service || null,
        sessionId,
        clarify: clarifyText(),
      },
    },
  ];
}

// ---------------------------------------------------------------------------
// 8. Nothing matched. There is no model behind this — every path ends in a
//    written answer, so the catch-all has to be genuinely useful rather than a
//    dead end. It never guesses at facts and never assumes a quote is wanted.
// ---------------------------------------------------------------------------

const MENUS = [
  'I can help with what we clean, the areas we cover, hours and after-hours work, insurance and police checks, and how quoting works. Jobs and existing accounts I hand straight to the team.',
  'Things I can answer: our services, coverage across Adelaide, scheduling and after-hours cleans, insurance and staff checks, and how a quote is put together. Anything about a job application or a live account goes to the team.',
  'Ask me about services, coverage, scheduling, insurance and police checks, or the quoting process. For roles, invoices or an existing schedule, the team is the right stop.',
];

const SOFT = [
  /\bclean/,
  /\bservice/,
  /\bsite|premises|building|floor|toilet|amenit/,
];

const QUESTION = /\b(what|when|where|why|how|which|who|can you|could you|do you|does|are you|is it|would you)\b|\?$/;

const fbBase = seed(sessionId + '|fallback|' + turn);
let fbReply;

if (SOFT.some((re) => re.test(text))) {
  // Cleaning-adjacent but unclassified: answer with the range, then ask.
  fbReply = [
    pick(BODIES.services_list.bodies, fbBase),
    pick(NEXT.detail, fbBase >> 3),
  ].join(' ');
} else if (QUESTION.test(text)) {
  fbReply = [
    pick([
      "I'm not confident I'd answer that one properly, and I'd rather not guess.",
      "That's outside what I can answer accurately from here.",
      "I don't want to give you a half-right answer on that.",
    ], fbBase),
    pick(MENUS, fbBase >> 3),
    pick([
      `For anything else, ${B.phone} reaches the team directly.`,
      `Anything beyond that, call ${B.phone} or email ${B.email}.`,
      `${B.phone} during ${B.hoursShort} gets you a person.`,
    ], fbBase >> 6),
  ].join(' ');
} else {
  fbReply = [
    pick([
      'Happy to help — I just want to point you the right way.',
      "Let me make sure you get to the right place.",
      'Tell me a little more and I can point you the right way.',
    ], fbBase),
    pick(MENUS, fbBase >> 3),
  ].join(' ');
}

return [
  {
    json: {
      direct: true,
      reply: fbReply,
      intent: 'general',
      confidence: 'low',
      service: service || null,
      sessionId,
      clarify: clarifyText(),
    },
  },
];
